//! Customer-controlled conditional engineering grants. No deployment is authorized.
#[path="../../shared/model.rs"] mod model;
pub use model::FeatureId;use model::*;
use near_sdk::{near,env,ext_contract,AccountId,NearToken,Gas,Promise,PromiseError,PanicOnDefault};
use near_sdk::json_types::{U128,U64};use near_sdk::store::LookupMap;
type CampaignKey=(AccountId,String);type ClaimKey=(AccountId,String,AccountId);
#[near(serializers=[borsh,json])]
#[derive(Clone)]
pub struct Campaign {pub merchant:AccountId,pub feature:FeatureId,pub developer:AccountId,pub source_terms_hash:String,pub target:U128,pub committed:U128,pub funding_deadline:U64,pub delivery_deadline:U64,pub funded:bool,pub cancelled:bool,pub storage_available:U128,pub artifact:String,pub verified:bool,pub verification_pending:bool,pub verification_nonce:U64}
#[near(serializers=[borsh,json])]
#[derive(Clone,PartialEq,Eq,Debug)]
pub enum ClaimStatus {Held,PendingRefund,PendingRelease,Refunded,Released}
#[near(serializers=[borsh,json])]
#[derive(Clone)]
pub struct Claim {pub amount:U128,pub status:ClaimStatus,pub nonce:U64}
#[near(contract_state)]
#[derive(PanicOnDefault)]
pub struct Commitments {marketplace:AccountId,campaigns:LookupMap<CampaignKey,Campaign>,claims:LookupMap<ClaimKey,Claim>,bootstrap:u128,storage_funded:u128,held:u128,pending:u128,contributed:u128,refunded:u128,released:u128}
#[ext_contract(ext_source)]
#[allow(dead_code)]trait Marketplace {fn get_release(&self,feature:FeatureId)->Option<model::SourceRelease>;}
#[ext_contract(ext_self)]
#[allow(dead_code)]trait Callbacks {fn on_delivery(&mut self,merchant:AccountId,campaign_id:String,nonce:U64)->bool;fn on_payment(&mut self,merchant:AccountId,campaign_id:String,buyer:AccountId,nonce:U64)->bool;}
#[near]
impl Commitments {
 #[init]pub fn new(marketplace:AccountId)->Self{assert!(!env::state_exists(),"ALREADY_INITIALIZED");let bootstrap=cost(env::storage_usage()+4096);assert!(env::account_balance().as_yoctonear()>=bootstrap,"BOOTSTRAP_UNFUNDED");Self{marketplace,campaigns:LookupMap::new(b"c"),claims:LookupMap::new(b"p"),bootstrap,storage_funded:0,held:0,pending:0,contributed:0,refunded:0,released:0}}
 #[payable]pub fn create_campaign(&mut self,campaign_id:String,feature:FeatureId,developer:AccountId,source_terms_hash:String,target:U128,funding_deadline:U64,delivery_deadline:U64)->Campaign{
 id(&campaign_id);feature.validate();digest(&source_terms_hash);let merchant=env::predecessor_account_id();assert_eq!(merchant,feature.owner,"NOT_MERCHANT");assert!(target.0>0&&funding_deadline.0>env::block_timestamp()&&delivery_deadline.0>funding_deadline.0,"INVALID_AGREEMENT");let key=(merchant.clone(),campaign_id);assert!(!self.campaigns.contains_key(&key),"DUPLICATE_CAMPAIGN");let deposit=env::attached_deposit().as_yoctonear();assert!(deposit>=cost(8192),"STORAGE_UNFUNDED");self.check(add(self.storage_funded,deposit),self.held,self.pending);let before=env::storage_usage();self.storage_funded=add(self.storage_funded,deposit);self.campaigns.insert(key.clone(),Campaign{merchant,feature,developer,source_terms_hash,target,committed:U128(0),funding_deadline,delivery_deadline,funded:false,cancelled:false,storage_available:U128(deposit),artifact:"0".repeat(64),verified:false,verification_pending:false,verification_nonce:U64(0)});self.charge(&key,before,8192);event("campaign_created",&key);self.campaigns.get(&key).unwrap().clone()
 }
 #[payable]pub fn fund_storage(&mut self,campaign_id:String){id(&campaign_id);let key=(env::predecessor_account_id(),campaign_id);let mut c=self.campaigns.get(&key).expect("UNKNOWN_CAMPAIGN").clone();let d=env::attached_deposit().as_yoctonear();assert!(d>0,"INVALID_AMOUNT");self.check(add(self.storage_funded,d),self.held,self.pending);c.storage_available.0=add(c.storage_available.0,d);self.storage_funded=add(self.storage_funded,d);self.campaigns.insert(key,c);self.flush();}
 #[payable]pub fn commit(&mut self,merchant:AccountId,campaign_id:String)->Claim{
 id(&campaign_id);let key=(merchant.clone(),campaign_id.clone());let mut c=self.campaigns.get(&key).expect("UNKNOWN_CAMPAIGN").clone();assert!(!c.cancelled&&!c.funded&&env::block_timestamp()<c.funding_deadline.0,"FUNDING_CLOSED");let amount=env::attached_deposit().as_yoctonear();assert!(amount>0&&amount<=c.target.0-c.committed.0,"INVALID_AMOUNT");let buyer=env::predecessor_account_id();let ck=(merchant,campaign_id,buyer);let mut claim=self.claims.get(&ck).cloned().unwrap_or(Claim{amount:U128(0),status:ClaimStatus::Held,nonce:U64(0)});assert_eq!(claim.status,ClaimStatus::Held,"CLAIM_NOT_HELD");assert!(c.storage_available.0>=cost(4096),"STORAGE_UNFUNDED");self.check(self.storage_funded,add(self.held,amount),self.pending);self.flush();let before=env::storage_usage();claim.amount.0=add(claim.amount.0,amount);c.committed.0=add(c.committed.0,amount);c.funded=c.committed==c.target;self.held=add(self.held,amount);self.contributed=add(self.contributed,amount);self.claims.insert(ck.clone(),claim.clone());self.campaigns.insert(key.clone(),c);self.charge(&key,before,4096);event("commitment_held",&(ck,claim.amount));claim
 }
 pub fn cancel(&mut self,campaign_id:String){let key=(env::predecessor_account_id(),campaign_id);let c=self.campaigns.get_mut(&key).expect("UNKNOWN_CAMPAIGN");assert!(!c.cancelled,"ALREADY_CANCELLED");c.cancelled=true;self.flush();event("campaign_cancelled",key);}
 pub fn verify_delivery(&mut self,merchant:AccountId,campaign_id:String)->Promise{let key=(merchant.clone(),campaign_id.clone());let mut c=self.campaigns.get(&key).expect("UNKNOWN_CAMPAIGN").clone();assert!(c.funded&&!c.cancelled&&!c.verification_pending&&!c.verified&&env::block_timestamp()<c.delivery_deadline.0,"VERIFICATION_UNAVAILABLE");c.verification_nonce.0=c.verification_nonce.0.checked_add(1).expect("OVERFLOW");c.verification_pending=true;let nonce=c.verification_nonce;let feature=c.feature.clone();self.campaigns.insert(key,c);self.flush();ext_source::ext(self.marketplace.clone()).with_static_gas(Gas::from_tgas(15)).get_release(feature).then(ext_self::ext(env::current_account_id()).with_static_gas(Gas::from_tgas(25)).on_delivery(merchant,campaign_id,nonce))}
 #[private]pub fn on_delivery(&mut self,merchant:AccountId,campaign_id:String,nonce:U64)->bool{private();let key=(merchant,campaign_id);let mut c=self.campaigns.get(&key).expect("UNKNOWN_CAMPAIGN").clone();assert!(c.verification_pending&&c.verification_nonce==nonce,"STALE_VERIFICATION");c.verification_pending=false;let artifact=env::promise_result_checked(0,4096).ok().and_then(|b|source(&b,&c.feature,&c.developer,&c.source_terms_hash));let ok=!c.cancelled&&env::block_timestamp()<c.delivery_deadline.0&&artifact.is_some();if ok{c.artifact=artifact.unwrap();c.verified=true;}self.campaigns.insert(key.clone(),c);self.flush();event("delivery_checked",(key,ok));ok}
 pub fn release(&mut self,merchant:AccountId,campaign_id:String,expected_artifact_sha256:String)->Promise{digest(&expected_artifact_sha256);let c=self.campaigns.get(&(merchant.clone(),campaign_id.clone())).expect("UNKNOWN_CAMPAIGN");assert!(c.funded&&c.verified&&!c.cancelled&&env::block_timestamp()<c.delivery_deadline.0,"RELEASE_UNAVAILABLE");assert_eq!(c.artifact,expected_artifact_sha256,"ARTIFACT_MISMATCH");let developer=c.developer.clone();self.pay(merchant,campaign_id,developer,false)}
 pub fn refund(&mut self,merchant:AccountId,campaign_id:String)->Promise{let c=self.campaigns.get(&(merchant.clone(),campaign_id.clone())).expect("UNKNOWN_CAMPAIGN");assert!(c.cancelled||(!c.funded&&env::block_timestamp()>=c.funding_deadline.0)||env::block_timestamp()>=c.delivery_deadline.0,"REFUND_NOT_DUE");self.pay(merchant,campaign_id,env::predecessor_account_id(),true)}
 #[private]pub fn on_payment(&mut self,merchant:AccountId,campaign_id:String,buyer:AccountId,nonce:U64)->bool{private();let key=(merchant,campaign_id,buyer);let mut c=self.claims.get(&key).expect("UNKNOWN_CLAIM").clone();assert!(matches!(c.status,ClaimStatus::PendingRefund|ClaimStatus::PendingRelease)&&c.nonce==nonce,"STALE_PAYMENT");let ok=match env::promise_result_checked(0,0){Ok(_)=>true,Err(PromiseError::Failed)=>false,Err(_)=>panic!("PAYMENT_OUTCOME_UNKNOWN")};self.pending-=c.amount.0;if ok{if c.status==ClaimStatus::PendingRefund{self.refunded=add(self.refunded,c.amount.0);c.status=ClaimStatus::Refunded;}else{self.released=add(self.released,c.amount.0);c.status=ClaimStatus::Released;}}else{self.held=add(self.held,c.amount.0);c.status=ClaimStatus::Held;}self.claims.insert(key.clone(),c);self.flush();event("commitment_payment",(key,nonce,ok));ok}
 pub fn get_campaign(&self,merchant:AccountId,campaign_id:String)->Option<Campaign>{self.campaigns.get(&(merchant,campaign_id)).cloned()}
 pub fn config(&self)->near_sdk::serde_json::Value{near_sdk::serde_json::json!({"contract_version":"earnpatch-commitments-v1","marketplace":self.marketplace,"release_policy":"individual_customer_acceptance_of_verified_source_artifact","storage_refundable":false})}
 pub fn get_claim(&self,merchant:AccountId,campaign_id:String,buyer:AccountId)->Option<Claim>{self.claims.get(&(merchant,campaign_id,buyer)).cloned()}
 pub fn accounting(&self)->near_sdk::serde_json::Value{near_sdk::serde_json::json!({"contributed":U128(self.contributed),"held":U128(self.held),"pending":U128(self.pending),"refunded":U128(self.refunded),"released":U128(self.released),"storage_funded":U128(self.storage_funded),"conserved":self.contributed==self.held+self.pending+self.refunded+self.released,"conservatively_backed_including_pending":env::account_balance().as_yoctonear()>=self.required(self.storage_funded,self.held,self.pending)})}
}
impl Commitments {
 fn required(&self,storage:u128,held:u128,pending:u128)->u128{add(add(add(self.bootstrap,storage),held),pending)}
 fn check(&self,storage:u128,held:u128,pending:u128){assert!(env::account_balance().as_yoctonear()>=self.required(storage,held,pending),"INSOLVENT");}
 fn flush(&mut self){self.campaigns.flush();self.claims.flush();}
 fn charge(&mut self,key:&CampaignKey,before:u64,bound:u64){self.flush();let delta=env::storage_usage().checked_sub(before).expect("UNEXPECTED_SHRINK");assert!(delta<=bound,"STORAGE_BOUND");let c=self.campaigns.get_mut(key).unwrap();c.storage_available.0=c.storage_available.0.checked_sub(cost(delta)).expect("STORAGE_UNFUNDED");self.flush();}
 fn pay(&mut self,merchant:AccountId,campaign_id:String,payee:AccountId,refund:bool)->Promise{let buyer=env::predecessor_account_id();let key=(merchant.clone(),campaign_id.clone(),buyer.clone());let mut c=self.claims.get(&key).expect("UNKNOWN_CLAIM").clone();assert_eq!(c.status,ClaimStatus::Held,"CLAIM_NOT_HELD");self.check(self.storage_funded,self.held,self.pending);c.nonce.0=c.nonce.0.checked_add(1).expect("OVERFLOW");c.status=if refund{ClaimStatus::PendingRefund}else{ClaimStatus::PendingRelease};let amount=c.amount;let nonce=c.nonce;self.held-=amount.0;self.pending=add(self.pending,amount.0);self.claims.insert(key,c);self.flush();Promise::new(payee).transfer(NearToken::from_yoctonear(amount.0)).then(ext_self::ext(env::current_account_id()).with_static_gas(Gas::from_tgas(20)).on_payment(merchant,campaign_id,buyer,nonce))}
}
#[cfg(test)] mod tests;
